-- Bank reconciliation is a clearing layer over immutable GL cash lines; importing/matching never posts money.
CREATE TABLE accounting.bank_statements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),bank_account_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),from_date date NOT NULL,to_date date NOT NULL,opening_balance numeric(20,2) NOT NULL,closing_balance numeric(20,2) NOT NULL,source_format text NOT NULL CHECK(source_format IN('JSON','CSV')),source_hash text NOT NULL CHECK(source_hash~'^[0-9a-f]{64}$'),source_content bytea NOT NULL CHECK(octet_length(source_content)<=2097152),fingerprint text NOT NULL CHECK(fingerprint~'^[0-9a-f]{64}$'),line_count int NOT NULL CHECK(line_count BETWEEN 0 AND 5000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,bank_account_id,id),UNIQUE(company_id,bank_account_id,reference),UNIQUE(company_id,bank_account_id,fingerprint),FOREIGN KEY(company_id,bank_account_id) REFERENCES accounting.bank_accounts(company_id,id),CHECK(to_date>=from_date AND to_date-from_date<=366));
CREATE TABLE accounting.bank_statement_controls(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),state text NOT NULL DEFAULT 'OPEN' CHECK(state IN('OPEN','RECONCILED','VOID')),version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,id) REFERENCES accounting.bank_statements(company_id,id));
CREATE TABLE accounting.bank_statement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),statement_id uuid NOT NULL,bank_account_id uuid NOT NULL,line_no int NOT NULL CHECK(line_no>0),transaction_date date NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount<>0),description text NOT NULL CHECK(length(description)<=1000),reference text NOT NULL CHECK(length(reference)<=200),external_id text CHECK(length(btrim(external_id)) BETWEEN 1 AND 200),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,bank_account_id,id),UNIQUE(company_id,statement_id,line_no),UNIQUE(company_id,statement_id,external_id),FOREIGN KEY(company_id,bank_account_id,statement_id) REFERENCES accounting.bank_statements(company_id,bank_account_id,id));
CREATE TABLE accounting.bank_external_keys(company_id uuid NOT NULL REFERENCES core.companies(id),bank_account_id uuid NOT NULL,external_id text NOT NULL,line_id uuid NOT NULL,PRIMARY KEY(company_id,bank_account_id,external_id),FOREIGN KEY(company_id,bank_account_id,line_id) REFERENCES accounting.bank_statement_lines(company_id,bank_account_id,id));
CREATE TABLE accounting.bank_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),statement_line_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,statement_line_id) REFERENCES accounting.bank_statement_lines(company_id,id));
CREATE TABLE accounting.bank_match_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),match_id uuid NOT NULL,journal_line_id uuid NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),UNIQUE(company_id,id),UNIQUE(company_id,match_id,journal_line_id),FOREIGN KEY(company_id,match_id) REFERENCES accounting.bank_matches(company_id,id),FOREIGN KEY(company_id,journal_line_id) REFERENCES accounting.journal_lines(company_id,id));
CREATE TABLE accounting.bank_match_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),match_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,match_id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,match_id) REFERENCES accounting.bank_matches(company_id,id));
CREATE TABLE accounting.bank_reconciliations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),statement_id uuid NOT NULL,bank_account_id uuid NOT NULL,previous_reconciliation_id uuid,from_date date NOT NULL,to_date date NOT NULL,opening_balance numeric(20,2) NOT NULL,closing_balance numeric(20,2) NOT NULL,book_closing numeric(30,2) NOT NULL,outstanding_deposits numeric(30,2) NOT NULL CHECK(outstanding_deposits>=0),outstanding_payments numeric(30,2) NOT NULL CHECK(outstanding_payments>=0),reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,bank_account_id,statement_id) REFERENCES accounting.bank_statements(company_id,bank_account_id,id),FOREIGN KEY(company_id,previous_reconciliation_id) REFERENCES accounting.bank_reconciliations(company_id,id),CHECK(book_closing-outstanding_deposits+outstanding_payments=closing_balance));
CREATE TABLE accounting.bank_opening_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),reconciliation_id uuid NOT NULL,journal_line_id uuid NOT NULL,amount numeric(20,2) NOT NULL CHECK(amount>0),UNIQUE(company_id,id),UNIQUE(company_id,reconciliation_id,journal_line_id),FOREIGN KEY(company_id,reconciliation_id) REFERENCES accounting.bank_reconciliations(company_id,id),FOREIGN KEY(company_id,journal_line_id) REFERENCES accounting.journal_lines(company_id,id));
CREATE TABLE accounting.bank_reconciliation_reopens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),reconciliation_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference)) BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,reconciliation_id),UNIQUE(company_id,reference),FOREIGN KEY(company_id,reconciliation_id) REFERENCES accounting.bank_reconciliations(company_id,id));
CREATE TABLE accounting.bank_reconciliation_matches(company_id uuid NOT NULL REFERENCES core.companies(id),reconciliation_id uuid NOT NULL,match_id uuid NOT NULL,PRIMARY KEY(company_id,reconciliation_id,match_id),FOREIGN KEY(company_id,reconciliation_id) REFERENCES accounting.bank_reconciliations(company_id,id),FOREIGN KEY(company_id,match_id) REFERENCES accounting.bank_matches(company_id,id));
CREATE TABLE accounting.bank_reconciliation_outstanding(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),reconciliation_id uuid NOT NULL,journal_line_id uuid NOT NULL,signed_remaining numeric(20,2) NOT NULL CHECK(signed_remaining<>0),UNIQUE(company_id,id),UNIQUE(company_id,reconciliation_id,journal_line_id),FOREIGN KEY(company_id,reconciliation_id) REFERENCES accounting.bank_reconciliations(company_id,id),FOREIGN KEY(company_id,journal_line_id) REFERENCES accounting.journal_lines(company_id,id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_statements','bank_statement_controls','bank_statement_lines','bank_external_keys','bank_matches','bank_match_allocations','bank_match_releases','bank_reconciliations','bank_opening_allocations','bank_reconciliation_reopens','bank_reconciliation_matches','bank_reconciliation_outstanding'] LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company())',t);IF t NOT IN('bank_statement_controls','bank_external_keys') THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END $$;
CREATE TRIGGER touch_version BEFORE UPDATE ON accounting.bank_statement_controls FOR EACH ROW EXECUTE FUNCTION core.touch_version();
CREATE INDEX ON accounting.bank_statements(company_id,bank_account_id,to_date,id);
CREATE INDEX ON accounting.bank_statement_lines(company_id,bank_account_id,transaction_date);
CREATE INDEX ON accounting.bank_match_allocations(company_id,journal_line_id);
CREATE INDEX ON accounting.bank_opening_allocations(company_id,journal_line_id);
CREATE INDEX ON accounting.bank_matches(company_id,statement_line_id);
CREATE INDEX ON accounting.bank_reconciliations(company_id,bank_account_id,to_date);
INSERT INTO identity.permissions(code,description) VALUES('accounting.bank_statements.read','Read imported statements and clearing'),('accounting.bank_statements.import','Import bank files'),('accounting.bank_statements.match','Allocate or release cash matches'),('accounting.bank_statements.reconcile','Finalize bank reconciliation'),('accounting.bank_statements.reopen','Reopen latest reconciliation'),('accounting.bank_statements.void','Void unused bank imports');
CREATE FUNCTION identity.seed_bank_reconciliation_roles(c uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN INSERT INTO identity.role_permissions(company_id,role_id,permission_code) SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE') AND p.code LIKE 'accounting.bank_statements.%' ON CONFLICT DO NOTHING;END $$;
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_bank_reconciliation_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE VIEW accounting.active_bank_matches WITH(security_invoker=true) AS SELECT m.*,l.statement_id,l.bank_account_id,l.amount AS statement_amount,l.transaction_date FROM accounting.bank_matches m JOIN accounting.bank_statement_lines l ON l.company_id=m.company_id AND l.id=m.statement_line_id JOIN accounting.bank_statement_controls c ON c.company_id=l.company_id AND c.id=l.statement_id WHERE c.state<>'VOID' AND NOT EXISTS(SELECT 1 FROM accounting.bank_match_releases u WHERE u.company_id=m.company_id AND u.match_id=m.id);
CREATE VIEW accounting.active_bank_reconciliations WITH(security_invoker=true) AS SELECT r.* FROM accounting.bank_reconciliations r WHERE NOT EXISTS(SELECT 1 FROM accounting.bank_reconciliation_reopens u WHERE u.company_id=r.company_id AND u.reconciliation_id=r.id);
CREATE VIEW accounting.bank_cash_positions WITH(security_invoker=true) AS SELECT l.id,l.company_id,l.account_id AS bank_account_id,l.journal_entry_id,j.posting_date,j.description,b.source_document_id,b.posting_kind,d.number AS source_number,d.document_type,l.debit-l.credit AS signed_amount,abs(l.debit-l.credit) AS amount,
 coalesce((SELECT sum(a.amount) FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE a.company_id=l.company_id AND a.journal_line_id=l.id),0)+coalesce((SELECT sum(o.amount) FROM accounting.bank_opening_allocations o JOIN accounting.active_bank_reconciliations r ON r.company_id=o.company_id AND r.id=o.reconciliation_id WHERE o.company_id=l.company_id AND o.journal_line_id=l.id),0) AS reserved_amount,
 coalesce((SELECT sum(a.amount) FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id JOIN accounting.bank_statement_controls s ON s.company_id=m.company_id AND s.id=m.statement_id WHERE a.company_id=l.company_id AND a.journal_line_id=l.id AND s.state='RECONCILED'),0)+coalesce((SELECT sum(o.amount) FROM accounting.bank_opening_allocations o JOIN accounting.active_bank_reconciliations r ON r.company_id=o.company_id AND r.id=o.reconciliation_id WHERE o.company_id=l.company_id AND o.journal_line_id=l.id),0) AS cleared_amount
 FROM accounting.journal_lines l JOIN accounting.accounts ac ON ac.company_id=l.company_id AND ac.id=l.account_id AND ac.control_kind='BANK' JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.source_document_id;
CREATE FUNCTION accounting.require_bank_reconciliation_access(permission text,bank uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 PERFORM purchase.require_access('accounting.bank_statements.read');PERFORM purchase.require_access('accounting.banks.read');PERFORM purchase.require_access('accounting.ledger.read');IF permission<>'accounting.bank_statements.read' THEN PERFORM purchase.require_access(permission);END IF;
 PERFORM 1 FROM accounting.bank_accounts a JOIN accounting.accounts g ON g.company_id=a.company_id AND g.id=a.id WHERE a.company_id=core.current_company() AND a.id=bank AND a.kind<>'CASH' AND g.kind='ASSET' AND g.control_kind='BANK';IF NOT FOUND THEN RAISE EXCEPTION 'Statement bank unavailable' USING ERRCODE='HT404';END IF;END $$;
CREATE FUNCTION accounting.lock_bank_reconciliation(bank uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('bank-reconciliation:'||core.current_company()::text||':'||bank::text,0));END $$;
CREATE FUNCTION accounting.import_bank_statement(bank uuid,p_reference text,p_from date,p_to date,p_open numeric,p_close numeric,fmt text,source text,items jsonb,p_content bytea) RETURNS TABLE(id uuid,created boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();sid uuid:=gen_random_uuid();lid uuid;x jsonb;seq int:=0;finger text;existing accounting.bank_statements;dt date;amt numeric;eid text;BEGIN
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.import',bank);PERFORM accounting.lock_bank_reconciliation(bank);
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_from IS NULL OR p_to IS NULL OR p_from=date '0001-01-01' OR p_to<p_from OR p_to-p_from>366 OR p_to>(SELECT (now() AT TIME ZONE timezone)::date FROM core.companies co WHERE co.id=c) OR p_open IS NULL OR p_close IS NULL OR p_open<>round(p_open,2) OR p_close<>round(p_close,2) OR fmt IS NULL OR fmt NOT IN('JSON','CSV') OR source IS NULL OR source!~'^[0-9a-f]{64}$' OR p_content IS NULL OR octet_length(p_content)>2097152 OR encode(sha256(p_content),'hex')<>source OR items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items)>5000 THEN RAISE EXCEPTION 'Invalid statement header, dates, balances or rows' USING ERRCODE='HR422';END IF;
 finger:=encode(sha256(convert_to(jsonb_build_object('reference',btrim(p_reference),'from',p_from,'to',p_to,'opening',p_open,'closing',p_close,'format',fmt,'source',source,'lines',items)::text,'UTF8')),'hex');
 SELECT * INTO existing FROM accounting.bank_statements WHERE company_id=c AND bank_account_id=bank AND fingerprint=finger;IF FOUND THEN RETURN QUERY SELECT existing.id,false;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_statements s JOIN accounting.bank_statement_controls st ON st.company_id=s.company_id AND st.id=s.id WHERE s.company_id=c AND s.bank_account_id=bank AND s.source_hash=source AND st.state<>'VOID' AND(s.line_count>0 OR jsonb_array_length(items)>0 OR daterange(s.from_date,s.to_date,'[]')&&daterange(p_from,p_to,'[]'))) THEN RAISE EXCEPTION 'This bank file is already imported with different metadata' USING ERRCODE='HR409';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(items)v WHERE nullif(btrim(v->>'externalId'),'') IS NOT NULL GROUP BY btrim(v->>'externalId') HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate bank transaction ID in file' USING ERRCODE='HR422';END IF;
 IF p_open+coalesce((SELECT sum((value->>'amount')::numeric) FROM jsonb_array_elements(items)),0)<>p_close THEN RAISE EXCEPTION 'Statement opening plus signed lines must equal closing' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.bank_statements(id,company_id,bank_account_id,reference,from_date,to_date,opening_balance,closing_balance,source_format,source_hash,source_content,fingerprint,line_count,created_by) VALUES(sid,c,bank,btrim(p_reference),p_from,p_to,p_open,p_close,fmt,source,p_content,finger,jsonb_array_length(items),core.current_actor());
 INSERT INTO accounting.bank_statement_controls(id,company_id) VALUES(sid,c);
 FOR x IN SELECT * FROM jsonb_array_elements(items) LOOP
 dt:=(x->>'date')::date;amt:=(x->>'amount')::numeric;eid:=nullif(btrim(x->>'externalId'),'');
 IF dt IS NULL OR dt<p_from OR dt>p_to OR amt IS NULL OR amt=0 OR amt<>round(amt,2) OR x->>'description' IS NULL OR length(x->>'description')>1000 OR x->>'reference' IS NULL OR length(x->>'reference')>200 OR length(eid)>200 THEN RAISE EXCEPTION 'Invalid statement line' USING ERRCODE='HR422';END IF;
 seq:=seq+1;lid:=gen_random_uuid();INSERT INTO accounting.bank_statement_lines(id,company_id,statement_id,bank_account_id,line_no,transaction_date,amount,description,reference,external_id) VALUES(lid,c,sid,bank,seq,dt,amt,x->>'description',x->>'reference',eid);
 IF eid IS NOT NULL THEN INSERT INTO accounting.bank_external_keys(company_id,bank_account_id,external_id,line_id) VALUES(c,bank,eid,lid);END IF;
 END LOOP;RETURN QUERY SELECT sid,true;END $$;
CREATE FUNCTION accounting.match_bank_line(line uuid,expected bigint,p_reference text,p_reason text,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();l accounting.bank_statement_lines;s accounting.bank_statements;st accounting.bank_statement_controls;mid uuid:=gen_random_uuid();x jsonb;j record;used numeric;amt numeric;total numeric:=0;BEGIN
 SELECT * INTO l FROM accounting.bank_statement_lines WHERE company_id=c AND id=line;IF NOT FOUND THEN RAISE EXCEPTION 'Statement line unavailable' USING ERRCODE='HT404';END IF;
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.match',l.bank_account_id);PERFORM accounting.lock_bank_reconciliation(l.bank_account_id);
 SELECT * INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=l.statement_id FOR UPDATE;SELECT * INTO s FROM accounting.bank_statements WHERE company_id=c AND id=l.statement_id;
 IF st.state<>'OPEN' OR expected IS NULL OR st.version<>expected THEN RAISE EXCEPTION 'Statement is closed or changed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items) NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM jsonb_array_elements(items)v GROUP BY v->>'journalLineId' HAVING count(*)>1) THEN RAISE EXCEPTION 'Reference, reason and distinct cash entries required' USING ERRCODE='HR422';END IF;
 SELECT coalesce(sum(a.amount),0) INTO used FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE m.company_id=c AND m.statement_line_id=line;
 INSERT INTO accounting.bank_matches(id,company_id,statement_line_id,reference,reason,created_by) VALUES(mid,c,line,btrim(p_reference),btrim(p_reason),core.current_actor());
 FOR x IN SELECT * FROM jsonb_array_elements(items) ORDER BY value->>'journalLineId' LOOP
 amt:=(x->>'amount')::numeric;SELECT * INTO j FROM accounting.bank_cash_positions WHERE company_id=c AND id=(x->>'journalLineId')::uuid AND bank_account_id=l.bank_account_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cash entry unavailable for this bank' USING ERRCODE='HT404';END IF;
 IF amt IS NULL OR amt<=0 OR amt<>round(amt,2) OR sign(j.signed_amount)<>sign(l.amount) OR j.posting_date>s.to_date OR amt>j.amount-j.reserved_amount THEN RAISE EXCEPTION 'Cash direction, date or remaining amount does not match' USING ERRCODE='HR409';END IF;
 total:=total+amt;INSERT INTO accounting.bank_match_allocations(company_id,match_id,journal_line_id,amount) VALUES(c,mid,j.id,amt);
 END LOOP;IF used+total>abs(l.amount) THEN RAISE EXCEPTION 'Allocation exceeds bank line remainder' USING ERRCODE='HR409';END IF;
 UPDATE accounting.bank_statement_controls SET state=state WHERE company_id=c AND id=l.statement_id;RETURN mid;END $$;
CREATE FUNCTION accounting.release_bank_match(p_match uuid,expected bigint,p_reference text,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=core.current_company();m record;st accounting.bank_statement_controls;uid uuid:=gen_random_uuid();BEGIN
 SELECT * INTO m FROM accounting.active_bank_matches WHERE company_id=c AND id=p_match;IF NOT FOUND THEN RAISE EXCEPTION 'Active match unavailable' USING ERRCODE='HT404';END IF;
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.match',m.bank_account_id);PERFORM accounting.lock_bank_reconciliation(m.bank_account_id);SELECT * INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=m.statement_id FOR UPDATE;
 IF st.state<>'OPEN' OR expected IS NULL OR expected<>st.version THEN RAISE EXCEPTION 'Statement closed or changed' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bank_match_releases(id,company_id,match_id,reference,reason,created_by) VALUES(uid,c,p_match,p_reference,p_reason,core.current_actor());UPDATE accounting.bank_statement_controls SET state=state WHERE company_id=c AND id=m.statement_id;RETURN uid;END $$;
CREATE FUNCTION accounting.finalize_bank_reconciliation(statement uuid,expected bigint,p_reference text,p_reason text,opening jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();s accounting.bank_statements;st accounting.bank_statement_controls;prior accounting.bank_reconciliations;rid uuid:=gen_random_uuid();x jsonb;j record;amt numeric;opening_total numeric:=0;book numeric;deposits numeric;payments numeric;BEGIN
 SELECT * INTO s FROM accounting.bank_statements WHERE company_id=c AND id=statement;IF NOT FOUND THEN RAISE EXCEPTION 'Statement unavailable' USING ERRCODE='HT404';END IF;
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.reconcile',s.bank_account_id);PERFORM accounting.lock_bank_reconciliation(s.bank_account_id);SELECT * INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=statement FOR UPDATE;
 IF st.state<>'OPEN' OR expected IS NULL OR expected<>st.version THEN RAISE EXCEPTION 'Statement closed or changed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR opening IS NULL OR jsonb_typeof(opening)<>'array' OR jsonb_array_length(opening)>5000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(opening)v GROUP BY v->>'journalLineId' HAVING count(*)>1) THEN RAISE EXCEPTION 'Reconciliation reference, reason and distinct opening entries required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_statement_lines l WHERE l.company_id=c AND l.statement_id=statement AND abs(l.amount)<>(SELECT coalesce(sum(a.amount),0) FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE m.company_id=c AND m.statement_line_id=l.id)) THEN RAISE EXCEPTION 'Every bank line must be fully matched' USING ERRCODE='HR409';END IF;
 SELECT * INTO prior FROM accounting.active_bank_reconciliations WHERE company_id=c AND bank_account_id=s.bank_account_id ORDER BY to_date DESC,id DESC LIMIT 1;
 IF prior.id IS NOT NULL AND(s.from_date<>prior.to_date+1 OR s.opening_balance<>prior.closing_balance OR jsonb_array_length(opening)>0) THEN RAISE EXCEPTION 'Statements must be consecutive and carry forward the prior closing balance' USING ERRCODE='HR409';END IF;
 -- Validate opening allocations before recording the immutable reconciliation; only the first statement accepts them.
 FOR x IN SELECT * FROM jsonb_array_elements(opening) ORDER BY value->>'journalLineId' LOOP
 amt:=(x->>'amount')::numeric;SELECT * INTO j FROM accounting.bank_cash_positions WHERE company_id=c AND id=(x->>'journalLineId')::uuid AND bank_account_id=s.bank_account_id;
 IF NOT FOUND OR amt IS NULL OR amt<=0 OR amt<>round(amt,2) OR j.posting_date>=s.from_date OR amt>j.amount-j.reserved_amount THEN RAISE EXCEPTION 'Invalid already-cleared opening cash entry' USING ERRCODE='HR409';END IF;opening_total:=opening_total+sign(j.signed_amount)*amt;
 END LOOP;
 IF prior.id IS NULL AND opening_total<>s.opening_balance THEN RAISE EXCEPTION 'Opening balance requires explicit already-cleared book entries' USING ERRCODE='HR409';END IF;
 WITH extra AS(SELECT (v->>'journalLineId')::uuid AS id,(v->>'amount')::numeric AS amount FROM jsonb_array_elements(opening)v), current_matches AS(SELECT a.journal_line_id AS id,sum(a.amount) AS amount FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE m.company_id=c AND m.statement_id=statement GROUP BY a.journal_line_id), calc AS(SELECT p.signed_amount,p.amount-p.cleared_amount-coalesce(e.amount,0)-coalesce(m.amount,0) AS remainder FROM accounting.bank_cash_positions p LEFT JOIN extra e ON e.id=p.id LEFT JOIN current_matches m ON m.id=p.id WHERE p.company_id=c AND p.bank_account_id=s.bank_account_id AND p.posting_date<=s.to_date)
 SELECT coalesce(sum(signed_amount),0),coalesce(sum(remainder)FILTER(WHERE signed_amount>0),0),coalesce(sum(remainder)FILTER(WHERE signed_amount<0),0) INTO book,deposits,payments FROM calc;
 IF book-deposits+payments<>s.closing_balance THEN RAISE EXCEPTION 'Adjusted book closing does not equal bank closing' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bank_reconciliations(id,company_id,statement_id,bank_account_id,previous_reconciliation_id,from_date,to_date,opening_balance,closing_balance,book_closing,outstanding_deposits,outstanding_payments,reference,reason,created_by) VALUES(rid,c,statement,s.bank_account_id,prior.id,s.from_date,s.to_date,s.opening_balance,s.closing_balance,book,deposits,payments,btrim(p_reference),btrim(p_reason),core.current_actor());
 INSERT INTO accounting.bank_opening_allocations(company_id,reconciliation_id,journal_line_id,amount) SELECT c,rid,(v->>'journalLineId')::uuid,(v->>'amount')::numeric FROM jsonb_array_elements(opening)v;
 INSERT INTO accounting.bank_reconciliation_matches(company_id,reconciliation_id,match_id) SELECT c,rid,id FROM accounting.active_bank_matches WHERE company_id=c AND statement_id=statement;
 UPDATE accounting.bank_statement_controls SET state='RECONCILED' WHERE company_id=c AND id=statement;
 INSERT INTO accounting.bank_reconciliation_outstanding(company_id,reconciliation_id,journal_line_id,signed_remaining) SELECT c,rid,id,sign(signed_amount)*(amount-cleared_amount) FROM accounting.bank_cash_positions WHERE company_id=c AND bank_account_id=s.bank_account_id AND posting_date<=s.to_date AND amount>cleared_amount;RETURN rid;END $$;
CREATE FUNCTION accounting.reopen_bank_reconciliation(reconciliation uuid,expected bigint,p_reference text,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=core.current_company();r accounting.bank_reconciliations;st accounting.bank_statement_controls;uid uuid:=gen_random_uuid();latest uuid;BEGIN
 SELECT * INTO r FROM accounting.active_bank_reconciliations WHERE company_id=c AND id=reconciliation;IF NOT FOUND THEN RAISE EXCEPTION 'Active reconciliation unavailable' USING ERRCODE='HT404';END IF;
 PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.reopen',r.bank_account_id);PERFORM accounting.lock_bank_reconciliation(r.bank_account_id);SELECT * INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=r.statement_id FOR UPDATE;
 SELECT id INTO latest FROM accounting.active_bank_reconciliations WHERE company_id=c AND bank_account_id=r.bank_account_id ORDER BY to_date DESC,id DESC LIMIT 1;
 IF latest IS DISTINCT FROM reconciliation OR expected IS NULL OR st.version<>expected OR st.state<>'RECONCILED' THEN RAISE EXCEPTION 'Only the latest unchanged reconciliation can reopen' USING ERRCODE='HR409';END IF;
 INSERT INTO accounting.bank_reconciliation_reopens(id,company_id,reconciliation_id,reference,reason,created_by) VALUES(uid,c,reconciliation,p_reference,p_reason,core.current_actor());UPDATE accounting.bank_statement_controls SET state='OPEN' WHERE company_id=c AND id=r.statement_id;RETURN uid;END $$;
CREATE FUNCTION accounting.void_bank_statement(statement uuid,expected bigint,p_reference text,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=core.current_company();s accounting.bank_statements;st accounting.bank_statement_controls;BEGIN
 SELECT * INTO s FROM accounting.bank_statements WHERE company_id=c AND id=statement;IF NOT FOUND THEN RAISE EXCEPTION 'Statement unavailable' USING ERRCODE='HT404';END IF;PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.void',s.bank_account_id);PERFORM accounting.lock_bank_reconciliation(s.bank_account_id);SELECT * INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND id=statement FOR UPDATE;
 IF expected IS NULL OR st.version<>expected OR st.state<>'OPEN' OR EXISTS(SELECT 1 FROM accounting.active_bank_matches WHERE company_id=c AND statement_id=statement) THEN RAISE EXCEPTION 'Only an unchanged open import without active matches can be voided' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Void reference and reason required' USING ERRCODE='HR422';END IF;
 DELETE FROM accounting.bank_external_keys k USING accounting.bank_statement_lines l WHERE k.company_id=c AND l.company_id=k.company_id AND l.id=k.line_id AND l.statement_id=statement;UPDATE accounting.bank_statement_controls SET state='VOID' WHERE company_id=c AND id=statement;RETURN statement;END $$;
-- All inserted BANK lines in a posting statement lock accounts in UUID order, then recheck the finalized watermark.
CREATE FUNCTION accounting.guard_reconciled_cash_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE x record;cutoff date;BEGIN
 FOR x IN SELECT DISTINCT n.company_id,n.account_id FROM bank_inserted n JOIN accounting.accounts a ON a.company_id=n.company_id AND a.id=n.account_id WHERE a.control_kind='BANK' ORDER BY n.company_id,n.account_id LOOP
 PERFORM pg_advisory_xact_lock(hashtextextended('bank-reconciliation:'||x.company_id::text||':'||x.account_id::text,0));SELECT max(to_date) INTO cutoff FROM accounting.active_bank_reconciliations WHERE company_id=x.company_id AND bank_account_id=x.account_id;
 IF cutoff IS NOT NULL AND EXISTS(SELECT 1 FROM bank_inserted n JOIN accounting.journal_entries j ON j.company_id=n.company_id AND j.id=n.journal_entry_id WHERE n.company_id=x.company_id AND n.account_id=x.account_id AND j.posting_date<=cutoff) THEN RAISE EXCEPTION 'Cash posting date is within a reconciled statement; reopen the latest reconciliation first' USING ERRCODE='HR409';END IF;END LOOP;RETURN NULL;END $$;
CREATE TRIGGER reconciled_cash_guard AFTER INSERT ON accounting.journal_lines REFERENCING NEW TABLE AS bank_inserted FOR EACH STATEMENT EXECUTE FUNCTION accounting.guard_reconciled_cash_insert();
REVOKE ALL ON FUNCTION identity.seed_bank_reconciliation_roles(uuid),accounting.require_bank_reconciliation_access(text,uuid),accounting.lock_bank_reconciliation(uuid),accounting.import_bank_statement(uuid,text,date,date,numeric,numeric,text,text,jsonb,bytea),accounting.match_bank_line(uuid,bigint,text,text,jsonb),accounting.release_bank_match(uuid,bigint,text,text),accounting.finalize_bank_reconciliation(uuid,bigint,text,text,jsonb),accounting.reopen_bank_reconciliation(uuid,bigint,text,text),accounting.void_bank_statement(uuid,bigint,text,text),accounting.guard_reconciled_cash_insert() FROM PUBLIC;
GRANT SELECT ON accounting.bank_statements,accounting.bank_statement_controls,accounting.bank_statement_lines,accounting.bank_external_keys,accounting.bank_matches,accounting.bank_match_allocations,accounting.bank_match_releases,accounting.bank_reconciliations,accounting.bank_opening_allocations,accounting.bank_reconciliation_reopens,accounting.active_bank_matches,accounting.active_bank_reconciliations,accounting.bank_cash_positions TO htt_app;
GRANT EXECUTE ON FUNCTION accounting.require_bank_reconciliation_access(text,uuid),accounting.import_bank_statement(uuid,text,date,date,numeric,numeric,text,text,jsonb,bytea),accounting.match_bank_line(uuid,bigint,text,text,jsonb),accounting.release_bank_match(uuid,bigint,text,text),accounting.finalize_bank_reconciliation(uuid,bigint,text,text,jsonb),accounting.reopen_bank_reconciliation(uuid,bigint,text,text),accounting.void_bank_statement(uuid,bigint,text,text) TO htt_app;
-- Deferred guards independently validate imported balances, clearing capacity and reconciliation projections.
CREATE FUNCTION accounting.validate_bank_clearing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=NEW.company_id;b uuid;row_data jsonb:=to_jsonb(NEW);token text:=coalesce(current_setting('htt.bank_clearing_dirty',true),'');cache_key text;BEGIN
 b:=nullif(row_data->>'bank_account_id','')::uuid;
 IF b IS NULL THEN
 IF TG_TABLE_NAME='bank_statement_controls' THEN SELECT bank_account_id INTO b FROM accounting.bank_statements WHERE company_id=c AND id=NEW.id;
 ELSIF row_data?'statement_line_id' THEN SELECT bank_account_id INTO b FROM accounting.bank_statement_lines WHERE company_id=c AND id=(row_data->>'statement_line_id')::uuid;
 ELSIF row_data?'match_id' THEN SELECT l.bank_account_id INTO b FROM accounting.bank_matches m JOIN accounting.bank_statement_lines l ON l.company_id=m.company_id AND l.id=m.statement_line_id WHERE m.company_id=c AND m.id=(row_data->>'match_id')::uuid;
 ELSE SELECT bank_account_id INTO b FROM accounting.bank_reconciliations WHERE company_id=c AND id=(row_data->>'reconciliation_id')::uuid;END IF;END IF;
 IF b IS NULL THEN RAISE EXCEPTION 'Bank clearing source missing' USING ERRCODE='23514';END IF;
 cache_key:='htt.bank_clear_'||replace(b::text,'-','');IF current_setting(cache_key,true)=c::text||':'||token THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_statements s JOIN accounting.bank_statement_controls st ON st.company_id=s.company_id AND st.id=s.id WHERE s.company_id=c AND s.bank_account_id=b AND(s.line_count<>(SELECT count(*) FROM accounting.bank_statement_lines l WHERE l.company_id=c AND l.bank_account_id=b AND l.statement_id=s.id) OR s.opening_balance+coalesce((SELECT sum(l.amount) FROM accounting.bank_statement_lines l WHERE l.company_id=c AND l.bank_account_id=b AND l.statement_id=s.id),0)<>s.closing_balance OR (st.state='RECONCILED')<>(EXISTS(SELECT 1 FROM accounting.active_bank_reconciliations r WHERE r.company_id=c AND r.bank_account_id=b AND r.statement_id=s.id)))) THEN RAISE EXCEPTION 'Statement balance/state invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_cash_positions WHERE company_id=c AND bank_account_id=b AND(reserved_amount>amount OR cleared_amount>reserved_amount)) THEN RAISE EXCEPTION 'Cash clearing exceeds source entry' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.active_bank_matches m JOIN accounting.bank_statement_lines l ON l.company_id=m.company_id AND l.id=m.statement_line_id JOIN accounting.bank_statements s ON s.company_id=l.company_id AND s.id=l.statement_id JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id JOIN accounting.bank_cash_positions p ON p.company_id=a.company_id AND p.id=a.journal_line_id WHERE m.company_id=c AND m.bank_account_id=b AND(p.bank_account_id<>m.bank_account_id OR sign(p.signed_amount)<>sign(l.amount) OR p.posting_date>s.to_date)) OR EXISTS(SELECT 1 FROM accounting.bank_statement_lines l WHERE l.company_id=c AND l.bank_account_id=b AND(SELECT coalesce(sum(a.amount),0) FROM accounting.bank_match_allocations a JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE m.company_id=c AND m.bank_account_id=b AND m.statement_line_id=l.id)>abs(l.amount)) THEN RAISE EXCEPTION 'Bank match source/direction/amount invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.active_bank_reconciliations r LEFT JOIN accounting.active_bank_reconciliations prev ON prev.company_id=r.company_id AND prev.id=r.previous_reconciliation_id WHERE r.company_id=c AND r.bank_account_id=b AND(r.book_closing<>(SELECT coalesce(sum(p.signed_amount),0) FROM accounting.bank_cash_positions p WHERE p.company_id=c AND p.bank_account_id=r.bank_account_id AND p.posting_date<=r.to_date) OR (r.previous_reconciliation_id IS NOT NULL AND(prev.id IS NULL OR prev.bank_account_id<>r.bank_account_id OR prev.to_date+1<>r.from_date OR prev.closing_balance<>r.opening_balance)))) THEN RAISE EXCEPTION 'Reconciled book balance/chain invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_reconciliations r WHERE r.company_id=c AND r.bank_account_id=b AND(r.outstanding_deposits<>(SELECT coalesce(sum(greatest(o.signed_remaining,0)),0) FROM accounting.bank_reconciliation_outstanding o WHERE o.company_id=c AND o.reconciliation_id=r.id) OR r.outstanding_payments<>(SELECT coalesce(sum(greatest(-o.signed_remaining,0)),0) FROM accounting.bank_reconciliation_outstanding o WHERE o.company_id=c AND o.reconciliation_id=r.id))) THEN RAISE EXCEPTION 'Outstanding snapshot invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_statement_lines l JOIN accounting.bank_statement_controls st ON st.company_id=l.company_id AND st.id=l.statement_id WHERE l.company_id=c AND l.bank_account_id=b AND l.external_id IS NOT NULL AND st.state<>'VOID' AND NOT EXISTS(SELECT 1 FROM accounting.bank_external_keys k WHERE k.company_id=c AND k.bank_account_id=b AND k.bank_account_id=l.bank_account_id AND k.external_id=l.external_id AND k.line_id=l.id)) OR EXISTS(SELECT 1 FROM accounting.bank_external_keys k JOIN accounting.bank_statement_lines l ON l.company_id=k.company_id AND l.id=k.line_id JOIN accounting.bank_statement_controls st ON st.company_id=l.company_id AND st.id=l.statement_id WHERE k.company_id=c AND k.bank_account_id=b AND(st.state='VOID' OR k.external_id IS DISTINCT FROM l.external_id)) THEN RAISE EXCEPTION 'External transaction reservation invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_opening_allocations o JOIN accounting.bank_reconciliations r ON r.company_id=o.company_id AND r.id=o.reconciliation_id JOIN accounting.bank_cash_positions p ON p.company_id=o.company_id AND p.id=o.journal_line_id WHERE o.company_id=c AND(r.previous_reconciliation_id IS NOT NULL OR p.bank_account_id<>r.bank_account_id OR p.posting_date>=r.from_date OR o.amount>p.amount)) OR EXISTS(SELECT 1 FROM accounting.bank_reconciliations r WHERE r.company_id=c AND r.bank_account_id=b AND r.previous_reconciliation_id IS NULL AND r.opening_balance<>(SELECT coalesce(sum(sign(p.signed_amount)*o.amount),0) FROM accounting.bank_opening_allocations o JOIN accounting.bank_cash_positions p ON p.company_id=o.company_id AND p.id=o.journal_line_id WHERE o.company_id=c AND o.reconciliation_id=r.id)) THEN RAISE EXCEPTION 'Opening clearing source invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bank_reconciliation_matches rm JOIN accounting.bank_reconciliations r ON r.company_id=rm.company_id AND r.id=rm.reconciliation_id JOIN accounting.bank_matches m ON m.company_id=rm.company_id AND m.id=rm.match_id JOIN accounting.bank_statement_lines l ON l.company_id=m.company_id AND l.id=m.statement_line_id WHERE rm.company_id=c AND l.statement_id<>r.statement_id) OR EXISTS(SELECT 1 FROM accounting.bank_reconciliation_outstanding o JOIN accounting.bank_reconciliations r ON r.company_id=o.company_id AND r.id=o.reconciliation_id JOIN accounting.bank_cash_positions p ON p.company_id=o.company_id AND p.id=o.journal_line_id WHERE o.company_id=c AND(p.bank_account_id<>r.bank_account_id OR p.posting_date>r.to_date OR sign(o.signed_remaining)<>sign(p.signed_amount) OR abs(o.signed_remaining)>p.amount)) THEN RAISE EXCEPTION 'Reconciliation snapshot source invariant failed' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM accounting.active_bank_reconciliations r WHERE r.company_id=c AND r.bank_account_id=b GROUP BY r.statement_id HAVING count(*)>1) OR EXISTS(SELECT 1 FROM accounting.bank_reconciliations r JOIN accounting.bank_statements st ON st.company_id=r.company_id AND st.id=r.statement_id WHERE r.company_id=c AND r.bank_account_id=b AND(r.from_date,r.to_date,r.opening_balance,r.closing_balance) IS DISTINCT FROM(st.from_date,st.to_date,st.opening_balance,st.closing_balance)) THEN RAISE EXCEPTION 'Reconciliation identity/state invariant failed' USING ERRCODE='23514';END IF;
 PERFORM set_config(cache_key,c::text||':'||token,true);RETURN NULL;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_statements','bank_statement_controls','bank_statement_lines','bank_external_keys','bank_matches','bank_match_allocations','bank_match_releases','bank_reconciliations','bank_opening_allocations','bank_reconciliation_reopens','bank_reconciliation_matches','bank_reconciliation_outstanding'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER bank_clearing_consistency AFTER INSERT OR UPDATE ON accounting.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_bank_clearing()',t);END LOOP;END $$;
REVOKE ALL ON FUNCTION accounting.validate_bank_clearing() FROM PUBLIC;

GRANT SELECT ON accounting.bank_reconciliation_matches,accounting.bank_reconciliation_outstanding TO htt_app;
CREATE FUNCTION accounting.mark_bank_clearing_dirty() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN PERFORM set_config('htt.bank_clearing_dirty',gen_random_uuid()::text,true);RETURN NULL;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_statements','bank_statement_controls','bank_statement_lines','bank_external_keys','bank_matches','bank_match_allocations','bank_match_releases','bank_reconciliations','bank_opening_allocations','bank_reconciliation_reopens','bank_reconciliation_matches','bank_reconciliation_outstanding'] LOOP EXECUTE format('CREATE TRIGGER invalidate_bank_clearing BEFORE INSERT OR UPDATE OR DELETE ON accounting.%I FOR EACH STATEMENT EXECUTE FUNCTION accounting.mark_bank_clearing_dirty()',t);END LOOP;END $$;
REVOKE ALL ON FUNCTION accounting.mark_bank_clearing_dirty() FROM PUBLIC;
